import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    private static final BigInteger MOD = BigInteger.valueOf(998244353L);
    private static final long MOD_LONG = 998244353L;
    private static final long INV2 = 499122177L;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner();
        PrintWriter out = new PrintWriter(System.out);
        long n = sc.nextInt();
        long m = sc.nextInt();
        long l = sc.nextInt();
        long r = sc.nextInt();
        long cells = n * m;
        String result = ModArithmetic.compute(l, r, cells);
        if (cells % 2 == 1) {
            out.print(result);
        } else {
            out.println(result);
        }
        out.flush();
    }

    static class ModArithmetic {
        static String compute(long l, long r, long cells) {
            long k = r - l;
            long even = k / 2 + 1;
            long odd = (k + 1) / 2;
            if (cells % 2 == 1) {
                return BigInteger.valueOf(k + 1).modPow(BigInteger.valueOf(cells), MOD).toString();
            }
            BigInteger temp1 = BigInteger.valueOf(even + odd).modPow(BigInteger.valueOf(cells), MOD);
            BigInteger temp2 = BigInteger.valueOf(even - odd).modPow(BigInteger.valueOf(cells), MOD);
            long sum = (temp1.longValue() + temp2.longValue()) % MOD_LONG;
            long ans = sum * INV2 % MOD_LONG;
            return String.valueOf(ans);
        }
    }

    static class Scanner {
        BufferedReader br;
        StringTokenizer st;

        Scanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
